using System;
using System.Collections.Generic;
using System.Linq;
using BepInEx.Configuration;
using Comfort.Common;
using EFT;
using UnityEngine;
using UnityEngine.AI;
namespace LocalSpt5Esp;
internal static class CompanionSquad {
 internal sealed class Member {
  internal LiveActorReference Actor=null!;internal string Ticket="",Name="",Status="已入队";internal CompanionOrder Order=CompanionOrder.Follow;
  internal int Index;internal float NextMove,NextAction,NextError;internal BotRequest? Request;internal Vector3 Goal;
  internal bool AttackOriginal,AttackSaved,WasPaused,Lost;internal Player? Target;internal bool Selected=true;
  internal readonly HashSet<string> Original=new(StringComparer.Ordinal),Delivered=new(StringComparer.Ordinal);
  internal CompanionLoot.Work Work=new();
 }
 sealed class Ticket {internal string Id="";internal SceneTemplate Entry=null!;internal int Index;internal bool Queued,Finished,Failed;internal float Since;}
 static readonly Dictionary<string,Member> members=new(StringComparer.Ordinal);static readonly Dictionary<string,Ticket> tickets=new(StringComparer.Ordinal);static CompanionSpawnLedger ledger=new();
 static IntPtr world;static string leader="",notice="尚未进入战局。";static float nextTick,nextQueue;static bool captured;static int desired;
 static ConfigEntry<KeyCode> followKey=null!,huntKey=null!,lootKey=null!,deliverKey=null!,holdKey=null!;
 static readonly Il2CppSystem.Action noop=(Action)(()=>{});static Vector2 scroll;static bool selectedOnly;
 internal static string Summary=>world==IntPtr.Zero?"下局将按保存的编队入场；首次自动生成后默认跟随玩家。":$"本局编队：已生成 {members.Count}/{desired} · 等待 {tickets.Values.Count(t=>!t.Finished)} · 失败 {tickets.Values.Count(t=>t.Failed)}。";
 internal static bool HasHunting=>members.Values.Any(m=>!m.Lost&&m.Order==CompanionOrder.Hunt);
 internal static void Initialize(){CompanionPlans.Initialize();const string section="51. 队友";followKey=FeatureConfig.Bind(section,"Squad follow key","队友跟随指令键",KeyCode.None);huntKey=FeatureConfig.Bind(section,"Squad hunt key","队友暴力清图指令键",KeyCode.None);lootKey=FeatureConfig.Bind(section,"Squad loot key","队友搜索物资指令键",KeyCode.None);deliverKey=FeatureConfig.Bind(section,"Squad deliver key","队友交付物资指令键",KeyCode.None);holdKey=FeatureConfig.Bind(section,"Squad hold key","队友原地待命指令键",KeyCode.None);}
 internal static bool IsMember(IPlayer? actor)=>actor!=null&&world!=IntPtr.Zero&&Singleton<GameWorld>.Instance?.Pointer==world&&members.TryGetValue(actor.ProfileId,out var m)&&actor.TryCast<Player>()?.Pointer==m.Actor.Pointer;
 internal static bool Friendly(IPlayer? a,IPlayer? b){var local=Singleton<GameWorld>.Instance?.MainPlayer;if(local==null||a==null||b==null||world==IntPtr.Zero||Singleton<GameWorld>.Instance?.Pointer!=world)return false;bool left=IsMember(a),right=IsMember(b);return left&&(right||b.ProfileId==local.ProfileId)||right&&a.ProfileId==local.ProfileId;}
 internal static bool? Relation(BotOwner owner,IPlayer target){var from=owner.GetPlayer;if(Friendly(from,target))return false;if(from==null||from.Profile?.Info?.Settings?.Role==WildSpawnType.shooterBTR||target.TryCast<Player>() is not {} other||other.HealthController?.IsAlive!=true||other.IsYourPlayer||!(other.IsAI||other.AIData?.BotOwner!=null)||other.Profile?.Info?.Settings?.Role==WildSpawnType.shooterBTR)return null;
  if(IsMember(from)&&members[from.ProfileId].Order==CompanionOrder.Hunt&&!AiTeamControl.IsTeammate(other))return true;
  if(IsMember(other)&&members[other.ProfileId].Order==CompanionOrder.Hunt&&!AiTeamControl.IsTeammate(from))return true;return null;
 }
 static Player Resolve(Member member)=>member.Actor.Resolve();
 internal static void Reset(){foreach(var member in members.Values){CompanionLoot.Retire(member);try{var actor=Resolve(member);StopRequest(member,actor);if(member.AttackSaved&&actor.AIData?.BotOwner?.Memory is {} memory){memory.AttackImmediately=member.AttackOriginal;memory.CheckIsPeace();}}catch{}}CompanionLoot.Reset();members.Clear();tickets.Clear();ledger=new();world=IntPtr.Zero;leader="";captured=false;desired=0;nextTick=nextQueue=0;}
 static void Capture(){if(captured)return;var roster=CompanionPlans.Snapshot();desired=roster.Sum(r=>r.Count);captured=true;int index=0;foreach(var entry in roster)for(int i=0;i<entry.Count;i++){string key=Guid.NewGuid().ToString("N");tickets[key]=new(){Id=key,Entry=entry,Index=index++,Since=Time.unscaledTime};ledger.Add(key);}notice=desired>0?"已接收本局编队，等待地图 AI 与导航就绪。":"编队为空，请先在战前编队页添加队友。";}
 static Vector3 SpawnPoint(GameWorld current,int index){var local=current.MainPlayer;float radius=CompanionPlans.SpawnDistance.Value+index/8*1.6f;float angle=(local.Rotation.x+index*137.5f)*Mathf.Deg2Rad;for(int attempt=0;attempt<16;attempt++){float a=angle+attempt*Mathf.PI/8;var candidate=local.Position+new Vector3(Mathf.Sin(a),0,Mathf.Cos(a))*radius;try{var point=AiSpawnService.Ground(candidate,local);if(Math.Abs(point.y-local.Position.y)>2)continue;if(Physics.Linecast(local.Position+Vector3.up,point+Vector3.up,LayerMask.GetMask("HighPolyCollider","Terrain","LowPolyCollider"),QueryTriggerInteraction.Ignore))continue;var path=new NavMeshPath();if(NavMesh.CalculatePath(local.Position,point,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete)return point;}catch{}}throw new ArgumentException("玩家附近尚无同层、可达的队友生成位置。");}
 static void QueueNext(GameWorld current){if(Time.unscaledTime<nextQueue||AiSpawnService.QueueCount>=4)return;nextQueue=Time.unscaledTime+.5f;var ticket=tickets.Values.FirstOrDefault(t=>!t.Queued&&!t.Finished);if(ticket==null)return;
  try{var entry=ticket.Entry;var option=AiSpawnCatalog.Options.First(o=>o.Role==entry.Role&&o.Side==entry.Side);var birth=entry.Birth with{Paused=true,PlayerRelation=1,AiRelation=0,Scene=null,LockedPose=null,SceneKey=""};AiSpawnService.Enqueue(current,SpawnPoint(current,ticket.Index),option,entry.Difficulty,1,birth,"战前编队 · "+entry.Name,false,ticket.Id);ticket.Queued=true;notice="正在生成队友："+entry.Name+"。";}
  catch(Exception e){notice="编队等待："+e.Message;if(Time.unscaledTime-ticket.Since>60){ticket.Failed=ticket.Finished=true;Plugin.Self.Log.LogWarning("Companion spawn position: "+e.Message);}}
 }
 internal static void Spawned(GameWorld current,Player actor,string key){if(current.Pointer!=world||!tickets.TryGetValue(key,out var ticket)||!ledger.Confirm(key,actor.ProfileId))return;var member=new Member{Actor=new(current,actor),Name=actor.Profile?.Nickname??ticket.Entry.Name,Ticket=key,Index=ticket.Index,WasPaused=false};members[actor.ProfileId]=member;CompanionLoot.CaptureOriginal(member,actor);
  try{var anchor=members.Values.Where(m=>m!=member).Select(m=>{try{return Resolve(m);}catch{return null;}}).FirstOrDefault(p=>p?.HealthController?.IsAlive==true);AiTeamControl.JoinCompanion(current,actor,anchor);ModelPoseLock.Release(actor);AiSceneDirector.Remove(actor);AiTestControl.SetPaused(new[]{actor},false);AiLimitCompatibility.Wake(actor);member.Status="已入队，跟随玩家";Plugin.Self.Log.LogInfo($"Companion joined: role={actor.Profile?.Info?.Settings?.Role}; profile={actor.ProfileId}; ticket={key}");}
  catch(Exception e){member.Status="组队待同步："+e.Message;notice=member.Status;Plugin.Self.Log.LogWarning("Companion join: "+e);}
 }
 internal static void RequestFinished(string key,int actual,int requested,string reason){if(!tickets.TryGetValue(key,out var ticket))return;ticket.Finished=true;ticket.Failed=actual==0&&!ledger.HasActor(key);if(ticket.Failed)notice="队友生成失败："+ticket.Entry.Name+" · "+reason;}
 internal static void RequestCancelled(string key){if(tickets.TryGetValue(key,out var ticket)){ticket.Finished=true;ticket.Failed=!ledger.HasActor(key);}}
 static bool InCombat(Player actor)=>actor.AIData?.BotOwner?.Memory?.GoalEnemy?.Person?.TryCast<Player>() is {} enemy&&enemy.HealthController?.IsAlive==true&&!Friendly(actor,enemy);
 internal static void StopRequest(Member member,Player actor){var request=member.Request;member.Request=null;if(request==null)return;var controller=actor.AIData?.BotOwner?.BotRequestController;try{if(controller?.CurRequest?.Pointer==request.Pointer)controller.CompleteRequest(request);else if(!request.Removed)request.Complete();}catch{}}
 static void SetRequest(Member member,Player actor,BotRequest request){var owner=actor.AIData?.BotOwner??throw new ArgumentException("队友 AI 尚未就绪。");var controller=owner.BotRequestController??throw new ArgumentException("队友指令控制器尚未就绪。");StopRequest(member,actor);request.AddPossibleExecutors(owner.Cast<IBotOwner>());if(!controller.GroupRequestController.TryAddRequest(request))request.SetGroup(controller.GroupRequestController);if(!request.Taken)request.Take(owner);controller.SetCurrentRequest(request);member.Request=request;}
 internal static bool Navigate(Member member,Player actor,Vector3 destination,float reach=2){if(Vector3.Distance(actor.Position,destination)<=reach)return true;if(Time.unscaledTime<member.NextMove)return false;member.NextMove=Time.unscaledTime+1;
  if(!NavMesh.SamplePosition(destination,out var sample,3,NavMesh.AllAreas)){member.Status="目的地附近没有导航地面";return false;}var path=new NavMeshPath();if(!NavMesh.CalculatePath(actor.Position,sample.position,NavMesh.AllAreas,path)||path.status!=NavMeshPathStatus.PathComplete){member.Status="目的地不可达，等待重新寻路";return false;}
  var owner=actor.AIData!.BotOwner;owner.Mover?.MovementResume();SetRequest(member,actor,new GoToPointRequest(Singleton<GameWorld>.Instance.MainPlayer,sample.position,noop,noop));member.Goal=sample.position;return false;
 }
 static Vector3 Formation(Member member,Player local){float angle=member.Index*137.5f*Mathf.Deg2Rad;float radius=CompanionPlans.FollowDistance.Value+(member.Index/8)*1.5f;return local.Position+new Vector3(Mathf.Sin(angle),0,Mathf.Cos(angle))*radius;}
 static void Follow(Member member,Player actor,Player local){if(InCombat(actor)){member.Status="跟随中，自卫交火";return;}if(Navigate(member,actor,Formation(member,local),2)){StopRequest(member,actor);actor.AIData?.BotOwner?.StopMove();member.Status="已到跟随位置";}else member.Status="正在跟随玩家";}
 static void Hunt(Member member,Player actor,GameWorld current){var all=current.AllAlivePlayersList;Player? chosen=null;float nearest=float.MaxValue;if(all!=null)for(int i=0;i<all.Count;i++){var candidate=all[i];if(candidate==null||candidate.Pointer==actor.Pointer||!CompanionRules.HuntTarget(candidate.HealthController?.IsAlive==true,candidate.IsAI||candidate.AIData?.BotOwner!=null,candidate.IsYourPlayer,AiTeamControl.IsTeammate(candidate)||IsMember(candidate),candidate.Profile?.Info?.Settings?.Role==WildSpawnType.shooterBTR))continue;float distance=(actor.Position-candidate.Position).sqrMagnitude;if(distance<nearest){nearest=distance;chosen=candidate;}}
  if(chosen==null){member.Target=null;Follow(member,actor,current.MainPlayer);member.Status="没有其他 AI，返回玩家附近";return;}
  StopRequest(member,actor);var owner=actor.AIData!.BotOwner;if(!member.AttackSaved){member.AttackSaved=true;member.AttackOriginal=owner.Memory.AttackImmediately;}AiActorControl.CommandAttack(owner,chosen);member.Target=chosen;member.Status="主动追击："+(chosen.Profile?.Nickname??"AI")+$" · {MathF.Sqrt(nearest):F0} 米";
 }
 static void Order(CompanionOrder order){if(!RaidClock.Active||world==IntPtr.Zero)throw new ArgumentException("进入战局并生成队友后才能下令。");var chosen=members.Values.Where(m=>!m.Lost&&(!selectedOnly||m.Selected)).ToArray();if(chosen.Length==0)throw new ArgumentException("没有可下令的队友。");int done=0;foreach(var member in chosen)try{var actor=Resolve(member);CompanionLoot.Cancel(member);StopRequest(member,actor);if(member.Target!=null){var owner=actor.AIData?.BotOwner;if(owner!=null)AiActorControl.Forget(owner,member.Target);member.Target=null;}if(member.AttackSaved&&actor.AIData?.BotOwner?.Memory is {} memory){memory.AttackImmediately=member.AttackOriginal;memory.CheckIsPeace();member.AttackSaved=false;}ModelPoseLock.Release(actor);AiSceneDirector.Remove(actor);AiTestControl.SetPaused(new[]{actor},false);AiLimitCompatibility.Wake(actor);member.Order=order;member.NextMove=member.NextAction=0;member.Status="已接收："+OrderName(order);done++;}catch(Exception e){member.Status="未执行："+e.Message;}notice=$"已向 {done}/{chosen.Length} 名队友下达“{OrderName(order)}”。";FeatureToasts.Show(notice);}
 static string OrderName(CompanionOrder order)=>order switch{CompanionOrder.Follow=>"跟随玩家",CompanionOrder.Hunt=>"暴力清图",CompanionOrder.Loot=>"搜索物资",CompanionOrder.Deliver=>"把物资丢给玩家",CompanionOrder.Hold=>"原地待命",_=>"自主行动"};
 internal static void Tick(GameWorld? current,Player? local){if(current==null||local?.HealthController?.IsAlive!=true){if(world!=IntPtr.Zero)Reset();return;}if(world!=current.Pointer||leader!=local.ProfileId){Reset();world=current.Pointer;leader=local.ProfileId;}
  if(!captured&&CompanionPlans.Automatic.Value)try{Capture();}catch(Exception e){captured=true;notice=e.Message;}
  if(!InterfaceMenu.InputBlocked){if((followKey.Value!=KeyCode.None&&Input.GetKeyDown(followKey.Value)))Action(()=>Order(CompanionOrder.Follow));if((huntKey.Value!=KeyCode.None&&Input.GetKeyDown(huntKey.Value)))Action(()=>Order(CompanionOrder.Hunt));if((lootKey.Value!=KeyCode.None&&Input.GetKeyDown(lootKey.Value)))Action(()=>Order(CompanionOrder.Loot));if((deliverKey.Value!=KeyCode.None&&Input.GetKeyDown(deliverKey.Value)))Action(()=>Order(CompanionOrder.Deliver));if((holdKey.Value!=KeyCode.None&&Input.GetKeyDown(holdKey.Value)))Action(()=>Order(CompanionOrder.Hold));}
  if(Time.unscaledTime<nextTick)return;nextTick=Time.unscaledTime+.35f;QueueNext(current);CompanionLoot.CollectRetired();foreach(var member in members.Values.ToArray())try{if(member.Lost)continue;var actor=Resolve(member);if(actor.HealthController?.IsAlive!=true){member.Status="队友已阵亡";CompanionLoot.Cancel(member);continue;}
   if(AiTeamControl.Group(actor)?.Pointer!=AiTeamControl.Group(local)?.Pointer||AiTeamControl.Group(local)==null){var anchor=members.Values.Where(m=>m!=member).Select(m=>{try{return Resolve(m);}catch{return null;}}).FirstOrDefault(p=>p?.HealthController?.IsAlive==true);AiTeamControl.JoinCompanion(current,actor,anchor);AiTestControl.SetPaused(new[]{actor},false);}
   if(CompanionLoot.Pending(member,current,actor))continue;
   switch(member.Order){case CompanionOrder.Follow:Follow(member,actor,local);break;case CompanionOrder.Hunt:Hunt(member,actor,current);break;case CompanionOrder.Loot:if(InCombat(actor)){member.Status="搜索中，自卫优先";break;}CompanionLoot.Search(member,current,actor,local);break;case CompanionOrder.Deliver:if(!InCombat(actor))CompanionLoot.Deliver(member,current,actor,local);else member.Status="交付暂停，自卫交火";break;case CompanionOrder.Hold:if(member.Request?.TryCast<HoldPositionRequest>()==null||member.Request.Removed)SetRequest(member,actor,new HoldPositionRequest(local,local.LookDirection));member.Status="原地待命，自卫照常";break;case CompanionOrder.Autonomous:member.Status="原生 AI 自主行动";break;}
  }catch(ArgumentException e){try{member.Actor.Resolve();member.Status="指令暂不可用："+e.Message;}catch{member.Lost=true;CompanionLoot.Retire(member);member.Request=null;member.Status="已阵亡或离开战局："+e.Message;}}catch(Exception e){member.Status="队友暂不可用："+e.Message;if(Time.unscaledTime>=member.NextError){member.NextError=Time.unscaledTime+15;Plugin.Self.Log.LogWarning("Companion command: "+e.Message);}}
 }
 static void Action(Action work){try{work();}catch(Exception e){notice=e.Message;FeatureToasts.Show(notice);}}
 internal static void Draw(Rect rect){float x=rect.x,y=rect.y,w=rect.width;InterfaceMenu.Label(new Rect(x,y,w,30),"队伍指令",InterfaceMenu.Accent,20);y+=42;InterfaceMenu.Paragraph(new Rect(x,y,w,40),Summary,null,13);y+=50;float half=(w-10)/2;
  if(InterfaceMenu.Button(new Rect(x,y,half,32),selectedOnly?"指令对象：已勾选队友":"指令对象：全体队友",selectedOnly))selectedOnly=!selectedOnly;
  bool old=GUI.enabled;GUI.enabled=old&&RaidClock.Active;if(InterfaceMenu.Button(new Rect(x+half+10,y,half,32),"补齐生成失败的队友"))Action(()=>{foreach(var ticket in tickets.Values.Where(t=>t.Failed&&!ledger.HasActor(t.Id))){ticket.Queued=ticket.Finished=ticket.Failed=false;ticket.Since=Time.unscaledTime;}if(!captured)Capture();});GUI.enabled=old;y+=44;
  var orders=Enum.GetValues<CompanionOrder>();int cols=MenuWorkspaceLayout.Columns(w,155);float cell=(w-8*(cols-1))/cols;for(int i=0;i<orders.Length;i++)if(InterfaceMenu.Button(new Rect(x+i%cols*(cell+8),y+i/cols*42,cell,34),OrderName(orders[i])))Action(()=>Order(orders[i]));y+=MathF.Ceiling(orders.Length/(float)cols)*42+12;
  var area=new Rect(x,y,w,Math.Max(70,rect.yMax-y-82));scroll=GUI.BeginScrollView(area,scroll,new Rect(0,0,w-22,Math.Max(area.height-1,members.Count*92)));int row=0;foreach(var member in members.Values){float top=row++*92;if(InterfaceMenu.Button(new Rect(2,top,34,32),member.Selected?"✓":"□",member.Selected))member.Selected=!member.Selected;InterfaceMenu.Label(new Rect(46,top,w-74,27),member.Name+" · "+OrderName(member.Order),InterfaceMenu.Accent,14);InterfaceMenu.Paragraph(new Rect(46,top+32,w-76,48),member.Status+" · 可交付物品 "+member.Work.CargoCount,null,12);}if(members.Count==0)InterfaceMenu.Paragraph(new Rect(8,12,w-40,80),"本局还没有编队队友。战前添加队友并开启自动生成；当前战局也可点击上方“补齐”提交一次已保存编队。",null,13);GUI.EndScrollView();InterfaceMenu.Paragraph(new Rect(x,rect.yMax-72,w,64),notice,InterfaceMenu.Accent,12);}
}
